        ConfigurationSource cfg = new ConfigurationSource(null, LineEnding.AUTO);

        cssFormatter.init(options, cfg);
        String code = "";
        String formattedCode = cssFormatter.doFormat(code, LineEnding.AUTO);

        assertNull(formattedCode);
    }
